use super::*;
fn doc<'a>(url:&'a str,text:Option<&'a str>,complete:bool)->NgramCorpusDocument<'a>{NgramCorpusDocument{requested_url:url,source_revision:Some("declared-revision"),capture_config_sha256:None,text_sha256:None,text,complete,basis:"declared_core_test",observed_generation:None}}
#[test]fn ngram_corpus_aggregates_more_than128_sources_exact_frequency_memberships_and_overlapping_positions(){let urls=(0..205).map(|n|format!("https://example.test/{n}")).collect::<Vec<_>>();let docs=urls.iter().map(|u|doc(u,Some("Red red red"),true)).collect::<Vec<_>>();let r=aggregate_saved_ngrams(&docs,&Default::default()).unwrap();let row=r.rows.iter().find(|r|r.tokens==["red","red"]).unwrap();assert_eq!(row.occurrences,410);assert_eq!(row.document_frequency,205);assert_eq!(row.sources.len(),205);assert_eq!(row.sources[204].source_ordinal,204);assert_eq!(row.sources[0].first_positions,vec![1,2]);assert_eq!(r.included_windows,[615,410,205]);assert_eq!(r.sources.len(),205);assert!(!r.whole_website_coverage_attested);}
#[test]fn ngram_corpus_existing_unicode_stopword_profile_never_bridges_sources_or_removed_words(){let options=NgramCorpusOptions{stopwords:vec!["und".into()],..Default::default()};let r=aggregate_saved_ngrams(&[doc("a",Some("Äpfel und Bäume"),true),doc("b",Some("ÄPFEL Bäume"),true)],&options).unwrap();assert!(r.rows.iter().any(|r|r.tokens==["äpfel","bäume"]&&r.occurrences==1));assert!(!r.rows.iter().any(|r|r.tokens==["bäume","äpfel"]));assert_eq!(r.excluded_stopword_windows,[1,2,1]);let preserve=NgramCorpusOptions{case_behavior:ContentCaseBehavior::Preserve,..Default::default()};let r=aggregate_saved_ngrams(&[doc("a",Some("A a"),true)],&preserve).unwrap();assert_eq!(r.rows.iter().filter(|r|r.n==1).count(),2);}
#[test]fn ngram_corpus_incomplete_missing_empty_duplicate_identity_and_tiny_budgets_are_explicit(){let docs=[doc("missing",None,false),doc("partial",Some("must not count"),false),doc("empty",Some(""),true)];let r=aggregate_saved_ngrams(&docs,&Default::default()).unwrap();assert!(r.rows.is_empty());assert_eq!(r.source_states["missing_or_unavailable"],1);assert_eq!(r.source_states["incomplete_excluded"],1);assert_eq!(r.source_states["complete_empty"],1);assert!(!r.all_supplied_sources_complete);assert_eq!(r.sources[1].counted,false);assert!(aggregate_saved_ngrams(&[doc("same",Some("one"),true),doc("same",Some("two"),true)],&Default::default()).is_err());for field in 0..4{let mut options=NgramCorpusOptions::default();match field{0=>options.limits.max_text_bytes=1,1=>options.limits.max_unique_ngrams=1,2=>options.limits.max_memberships=1,_=>options.limits.max_total_tokens=1};assert!(aggregate_saved_ngrams(&[doc("a",Some("one two three"),true)],&options).is_err());}}
#[test]fn ngram_corpus_position_sample_flag_preserves_full_count_and_actual_engine_positions(){let options=NgramCorpusOptions{limits:NgramCorpusLimits{position_samples:2,..Default::default()},..Default::default()};let r=aggregate_saved_ngrams(&[doc("a",Some("x x x x x"),true)],&options).unwrap();let row=r.rows.iter().find(|r|r.tokens==["x"]).unwrap();assert_eq!(row.occurrences,5);assert_eq!(row.sources[0].first_positions,vec![1,2]);assert!(row.sources[0].positions_sampled);assert_eq!(row.document_frequency,1);}
